PREFIX bs: <http://example.org/battlespace#>
SELECT ?weapon ?name WHERE {
  ?weapon a bs:SimulationType ;
          bs:warheadType ?wt ;
          bs:simTypeName ?name .
  FILTER regex(str(?wt), "Cluster", "i") .
}

